namespace CrissCross.Plot.TickGenerators;

/// <summary>A tick generator that produces no ticks.</summary>
public class EmptyTickGenerator : ITickGenerator
{
    /// <summary>Gets or sets the ticks generated by this instance.</summary>
    public Tick[] Ticks { get; set; } = Array.Empty<Tick>();

    /// <summary>Gets or sets the maximum number of ticks requested by the caller.</summary>
    public int MaxTickCount { get; set; } = 50;

    /// <summary>Regenerates ticks, leaving the tick collection empty.</summary>
    /// <param name="range">The visible coordinate range.</param>
    /// <param name="edge">The edge along which ticks would be rendered.</param>
    /// <param name="size">The available pixel length.</param>
    /// <param name="paint">The paint used to measure labels.</param>
    /// <param name="labelStyle">The style used for tick labels.</param>
    public void Regenerate(CoordinateRange range, Edge edge, PixelLength size, Paint paint, LabelStyle labelStyle)
    {
    }
}
